/* EVENT -> source site + call (pitch/queue live in the source; the runtime
 * owns the manager choice, published here for provenance).
 *   BT_AUDIO_EV_PLAYER_HURT      player.gd:440 Utils.get_rand_element(hurt_sounds); player.gd:507 play pitch 0.2 force
 *   BT_AUDIO_EV_PLAYER_DODGE     player.gd:442 Utils.get_rand_element(dodge_sounds) [second draw, only when dodging]
 *   BT_AUDIO_EV_HP_REGEN         player.gd:736 SoundManager.play(pick(hp_regen_sounds), get_heal_db(), 0.1)
 *   BT_AUDIO_EV_ALIEN_EYES       player.gd:855 SoundManager.play(pick(alien_sounds), 0, 0.1)
 *   BT_AUDIO_EV_GOLD_PICKUP      main.gd:804 SoundManager.play(pick(gold_pickup_sounds), 0, 0.2)
 *   BT_AUDIO_EV_LEVEL_UP         main.gd:863 SoundManager.play(level_up_sound, 0, 0, true) [DIRECT resource, no draw]
 *   BT_AUDIO_EV_END_WAVE         main.gd:958 SoundManager.play(pick(end_wave_sounds))
 *   BT_AUDIO_EV_RUN_WON          main.gd:1030 SoundManager.play(pick(run_won_sounds), -5, 0, true)
 *   BT_AUDIO_EV_RUN_LOST         main.gd:455 SoundManager.play(pick(run_lost_sounds), -5, 0, true)
 *   BT_AUDIO_EV_WEAPON_BREAK     player.gd:407 SoundManager.play(pick(WeaponService.breaking_sounds), -15, 0.1, true)
 *   BT_AUDIO_EV_BULL_EXPLODE     player.gd:560 if stats.shooting_sounds.size() > 0: play(pick, db, 0.2, true) [bull_item character explode_on_hit stats]
 *   BT_AUDIO_EV_GOLD_ALT_PICKUP  main.gd:802 SoundManager.play(pick(gold_alt_pickup_sounds), -5, 0.2) [only when ProgressData.settings.alt_gold_sounds]
 *   BT_AUDIO_EV_EXPLOSION_NODE   res://projectiles/explosion.tscn root PlayerExplosion.explosion_sounds; player_explosion.gd:31 SoundManager2D.play(pick(explosion_sounds), pos, sound_db_mod, 0.2) -- one draw per freshly instantiated node (gated on the node's sound_db_mod > -50)
 *   BT_AUDIO_EV_FLESH_EXPLOSION_NODE res://projectiles/flesh_explosion/flesh_explosion.tscn root PlayerExplosion.explosion_sounds; player_explosion.gd:31 SoundManager2D.play(pick(explosion_sounds), pos, sound_db_mod, 0.2) -- one draw per freshly instantiated node (gated on the node's sound_db_mod > -50)
 *   BT_AUDIO_EV_ONE_SHOT         unit.gd:750 SoundManager2D.play(effect.sound_one_shot, pos, 0, 0.2) [DIRECT stream]
 */

